/*
** fuzz/mkseeds.c -- deterministically write the seed corpus for Target A
** (fuzz/seeds/, one .bin file per stream).  Records follow fuzz/drv.h's
** opcode table exactly ([1B op][operands]); payload contents are
** regenerated by the harness from the stream's 8B seed, so only control
** bytes live here.
**
** Build/run tool, not part of the library.
*/
#include "drv.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

static uint8_t buf[1<<18];
static size_t n;

static void sb(uint64_t seed){
  int i;
  for(i=0; i<8; i++) buf[n++] = (uint8_t)(seed >> (8*i));
}
static void x(int o){ buf[n++] = (uint8_t)o; }

/* every op encoded with exactly its operand count */
static void curOpen(int h, int rt, int wrr){ x(FZ_OP_CUR_OPEN); x(h); x(rt); x(wrr); }
static void curClose(int h){ x(FZ_OP_CUR_CLOSE); x(h); }
static void beginTxn(int h, int wrr){ x(FZ_OP_BEGIN); x(h); x(wrr); }
static void commitT(int h){ x(FZ_OP_COMMIT); x(h); }
static void rbT(int h){ x(FZ_OP_ROLLBACK); x(h); }
/* RELEASE maps through byte%%2+1: byte 0 encodes it */
static void spR(int h, int i){ x(FZ_OP_SAVEPOINT); x(h); x(0); x(i); }
static void spRb(int h, int i){ x(FZ_OP_SAVEPOINT); x(h); x(1); x(i); }
static void createTree(int h){ x(FZ_OP_CREATE_TREE); x(h); }
static void clearTree(int h, int rt){ x(FZ_OP_CLEAR_TREE); x(h); x(rt); }
static void integrity(int h, int rt){ x(FZ_OP_INTEGRITY); x(h); x(rt); }
static void firstC(int h){ x(FZ_OP_FIRST); x(h); }
static void lastC(int h){ x(FZ_OP_LAST); x(h); }
static void nextC(int h){ x(FZ_OP_NEXT); x(h); }
static void prevC(int h){ x(FZ_OP_PREV); x(h); }
static void putk(int c, int klen, int kmode, int vlen){
  x(FZ_OP_PUT); x(c); x(klen); x(kmode); x(vlen);
}
static void getk(int c, int klen, int kmode){
  x(FZ_OP_GET); x(c); x(klen); x(kmode);
}
static void delk(int c, int klen, int kmode){
  x(FZ_OP_DEL); x(c); x(klen); x(kmode);
}
static void seekk(int c, int klen, int kmode){
  x(FZ_OP_SEEK); x(c); x(klen); x(kmode);
}
static void vread(int c, int off, int amt){
  x(FZ_OP_VALREAD); x(c); x(off); x(amt);
}
static void vwrite(int c, int off, int amt, int vm){
  x(FZ_OP_VALWRITE); x(c); x(off); x(amt); x(vm);
}
static void setint(int h){ x(FZ_OP_SETINT); x(h); }
static void ckp(int h, int mode){ x(FZ_OP_CHECKPOINT); x(h); x(mode); }
static void jmode(int h, int m){ x(FZ_OP_JOURNAL); x(h); x(m); }
static void syncK(int h, int l){ x(FZ_OP_SYNC); x(h); x(l); }
static void ackpt(int h, int nf){ x(FZ_OP_AUTOCKPT); x(h); x(nf); }

static void basicRw(int h){        /* open, write txn, tree, wr cursor */
  x(FZ_OP_OPEN); x(h); x(0);
  beginTxn(h, 1);
  createTree(h);
  curOpen(h, 0, 1);
}
static void fileOpen(int h){       /* file-backed flavor */
  x(FZ_OP_OPEN); x(h); x(1);
  beginTxn(h, 1);
  createTree(h);
  curOpen(h, 0, 1);
}
static void rdCursor(int h, int rt){  /* read txn + rd cursor on slot rt */
  beginTxn(h, 0);
  curOpen(h, rt, 0);
}

static void flush(const char *zn){
  char path[256];
  FILE *f;
  snprintf(path, sizeof path, "fuzz/seeds/%s.bin", zn);
  f = fopen(path, "wb");
  if( f==0 ){ fprintf(stderr, "mkseeds: cannot write %s\n", path); exit(1); }
  fwrite(buf, 1, n, f);
  fclose(f);
  n = 0;
}

int main(void){
  int i, j;
  mkdir("fuzz", 0777);
  mkdir("fuzz/seeds", 0777);

  /* s01: 100 monotone puts, commit, spot-gets, integrity */
  sb(0x01010101); basicRw(0);
  for(i=0;i<100;i++) putk(0, 9, 0, 8);
  commitT(0); rdCursor(0,0);
  for(i=0;i<8;i++) getk(0, 9, 0);
  integrity(0, 0);
  flush("s01-mono100");

  /* s02: 300 tiny-key puts, delete half */
  sb(0x02020202); basicRw(0);
  for(i=0;i<300;i++) putk(0, 9, 1, 6);
  for(i=0;i<150;i++) delk(0, 9, 1);
  commitT(0); integrity(0, 0);
  flush("s02-small300-del");

  /* s03/s04: random churn, two seeds */
  sb(0x0000000000000007ULL); basicRw(0);
  for(i=0;i<2000;i++){
    int a = i%5;
    if( a<2 ) putk(0, i%200, i%5, i%600);
    else if( a<4 ) getk(0, i%200, i%5);
    else delk(0, i%200, i%5);
  }
  commitT(0);
  flush("s03-churn2000-a");

  sb(0x0000000000000777ULL); basicRw(0);
  for(i=0;i<2000;i++){
    int a = (i*7)%5;
    if( a<3 ) putk(0, i%256, i%5, i%4096);
    else getk(0, i%256, i%5);
  }
  commitT(0);
  flush("s04-churn2000-b");

  /* s05: key length boundaries, raw-byte keys at full length */
  sb(0x05050505); basicRw(0);
  { int kl[8] = {0,1,3,127,128,129,253,255};
    for(j=0;j<8;j++) putk(0, kl[j], 3, 4);
    for(j=0;j<8;j++) putk(0, kl[j], 2, 4);   /* rewrite same keys */
    commitT(0); rdCursor(0,0);
    for(j=0;j<8;j++) getk(0, kl[j], 3);
  }
  commitT(0);
  flush("s05-keybounds");

  /* s06: value length tiers incl. spill boundaries */
  sb(0x06060606); basicRw(0);
  { int vl[12] = {0,1,10,488,489,490,3812,3813,3814,4092,8185,65536};
    for(j=0;j<12;j++) putk(0, 9, 0, vl[j]);
    commitT(0); rdCursor(0,0);
    for(j=0;j<12;j++) getk(0, 9, 0);
    for(j=0;j<12;j++) vread(0, 0, 1);
  }
  commitT(0);
  flush("s06-valbounds");

  /* s07: savepoint dance, five rounds */
  sb(0x07070707); basicRw(0);
  for(j=0;j<5;j++){
    for(i=0;i<20;i++) putk(0, 9, 0, 20);
    spR(0, 0);                          /* RELEASE 0 == commit */
    beginTxn(0, 1);
    for(i=0;i<10;i++) putk(0, 9, 1, 40);
    spRb(0, 1);                         /* ROLLBACK TO 1 */
    for(i=0;i<10;i++) putk(0, 9, 2, 60);
    commitT(0);
  }
  flush("s07-savepoint-dance");

  /* s08: empty-tree surface */
  sb(0x08080808);
  x(FZ_OP_OPEN); x(0); x(0);
  beginTxn(0, 1); createTree(0); curOpen(0, 0, 0);
  firstC(0); lastC(0); nextC(0); prevC(0);
  getk(0, 3, 1); seekk(0, 3, 1); delk(0, 3, 1);
  commitT(0);
  flush("s08-empty-ops");

  /* s09: clear/recreate loop */
  sb(0x09090909); basicRw(0);
  for(j=0;j<6;j++){
    for(i=0;i<30;i++) putk(0, 9, 0, 30);
    clearTree(0, 0);
    integrity(0, 0);
  }
  commitT(0);
  flush("s09-clear-loop");

  /* s10: four handles interleaved */
  sb(0x0a0a0a0a);
  for(i=0;i<4;i++){ x(FZ_OP_OPEN); x(i); x(0); beginTxn(i,1); createTree(i); curOpen(i,0,1); }
  for(j=0;j<50;j++) for(i=0;i<4;i++) putk(i, (j+i)%64, (j+i)%5, j%333);
  for(i=0;i<4;i++) commitT(i);
  flush("s10-multihandle");

  /* s11: seek sweep */
  sb(0x0b0b0b0b); basicRw(0);
  for(i=0;i<40;i++) putk(0, 9, 0, 20);
  for(i=0;i<120;i++) seekk(0, i%11+1, i%5);
  for(i=0;i<40;i++) seekk(0, (i%40)+1, 4);
  commitT(0);
  flush("s11-seek-sweep");

  /* s12: full walks forward and backward */
  sb(0x0c0c0c0c); basicRw(0);
  for(i=0;i<80;i++) putk(0, 9, 3, 24);
  commitT(0); rdCursor(0,0);
  for(i=0;i<85;i++) nextC(0);
  lastC(0);
  for(i=0;i<85;i++) prevC(0);
  commitT(0);
  flush("s12-scanwalks");

  /* s13: overwrite rounds (same keys, new values) */
  sb(0x0d0d0d0d); basicRw(0);
  for(j=0;j<3;j++){
    for(i=0;i<30;i++) putk(0, 6+i%3, 1, i+j);
    commitT(0); beginTxn(0, 1);
  }
  commitT(0);
  flush("s13-overwrite");

  /* s14: empty values */
  sb(0x0e0e0e0e); basicRw(0);
  for(i=0;i<40;i++) putk(0, 9, 0, 0);
  for(i=0;i<40;i++) getk(0, 9, 0);
  commitT(0);
  flush("s14-emptyvals");

  /* s15: big values, in- and out-of-range value_write probes */
  sb(0x0f0f0f0f); basicRw(0);
  for(i=0;i<8;i++) putk(0, 9, 0, 8185);
  for(i=0;i<16;i++){ vwrite(0, 0, 7, 0); }
  for(i=0;i<8;i++){ vwrite(0, 9, 1000, 1); }
  commitT(0);
  flush("s15-bigvals");

  /* s16: knob ops under memdb contracts */
  sb(0x10101010);
  x(FZ_OP_OPEN); x(0); x(0);
  jmode(0, 1);            /* WAL request -> 4 on memdb */
  jmode(0, 0);            /* 4 */
  syncK(0, 1);            /* -> 1, old 2 */
  syncK(0, 2);            /* -> 2, old 1 */
  ackpt(0, 5);
  ckp(0, 0);              /* no txn -> OK */
  beginTxn(0, 1);
  ckp(0, 0);              /* txn open -> LOCKED(6) */
  commitT(0);
  flush("s16-knobs");

  /* s17: interrupt path (flag is sticky; integrity must keep refusing) */
  sb(0x11111111); basicRw(0);
  for(i=0;i<50;i++) putk(0, 9, 0, 30);
  commitT(0);
  setint(0);
  integrity(0, 0); rdCursor(0,0); integrity(0, 0);
  commitT(0);
  flush("s17-interrupt");

  /* s18: maximal keys */
  sb(0x12121212); basicRw(0);
  for(i=0;i<150;i++) putk(0, 255, 2, 100);
  commitT(0);
  flush("s18-maxkeys");

  /* s19: bigger mixed churn */
  sb(0x0000000000001919ULL); basicRw(0);
  for(i=0;i<4000;i++){
    int a = (i*11)%7;
    if( a<3 ) putk(0,(i*13)%255,i%5,(i*7)%2048);
    else if( a<5 ) getk(0,(i*13)%255,i%5);
    else if( a==5 ) delk(0,(i*13)%255,i%5);
    else x(0);
  }
  commitT(0);
  flush("s19-mixed4000");

  /* s20: ROLLBACK TO 0 with cursor use in between */
  sb(0x14141414); basicRw(0);
  for(i=0;i<25;i++) putk(0, 9, 0, 40);
  spRb(0, 0);                                  /* whole-transaction undo */
  for(i=0;i<300;i++) seekk(0, i%9+1, i%3);
  for(i=0;i<10;i++) putk(0, 9, 1, 55);
  spRb(0, 0);
  commitT(0);
  flush("s20-rb0-cursor");

  /* s21: put/delete streaks on the same keys */
  sb(0x15151515); basicRw(0);
  for(j=0;j<10;j++){
    for(i=0;i<12;i++) putk(0, 7, 1, 30);
    for(i=0;i<12;i++) delk(0, 7, 1);
  }
  commitT(0);
  flush("s21-putdel-streak");

  /* s22: 16 cursors interleaved on one tree */
  sb(0x16161616); basicRw(0);
  for(i=0;i<30;i++) putk(0, 9, 0, 33);
  for(i=0;i<15;i++) curOpen(0, 0, i<8);
  for(j=0;j<200;j++){
    int c = j%16;
    int a = (j*3)%6;
    if( a==0 ) firstC(c);
    else if( a==1 ) nextC(c);
    else if( a==2 ) prevC(c);
    else if( a==3 ) getk(c, j%12+1, j%5);
    else if( a==4 ) putk(c, j%12+1, j%5, j%77);
    else lastC(c);
  }
  commitT(0);
  flush("s22-cur-chaos");

  /* s23: two trees, crossing traffic */
  sb(0x17171717); basicRw(0);
  createTree(0);
  curOpen(0, 1, 1);
  for(i=0;i<40;i++) putk(1, 8, 0, 44);
  for(i=0;i<40;i++) putk(0, 9, 1, 55);
  commitT(0);
  rdCursor(0,0); integrity(0, 0); integrity(0, 1);
  commitT(0);
  flush("s23-twotrees");

  /* s24: garbage bytes (decoder hygiene, no-op coverage) */
  sb(0x18181818);
  for(i=0;i<200;i++) x((i*29)+1);
  flush("s24-garbage");

  /* s25: journal-mode dance on a file handle.  Single-direction
  ** transitions only here: the full round trip lives in s27 (it is
  ** verified since the NOTADB fix; see s27's comment). */
  sb(0x25252525); fileOpen(0);
  for(i=0;i<10;i++) putk(0, 9, 0, 30);
  jmode(0, 1);            /* request WAL, current == WAL: stays 5 */
  jmode(0, 0);            /* request MEMORY inside txn -> ERROR */
  commitT(0);
  beginTxn(0, 1);
  for(i=0;i<10;i++) putk(0, 9, 1, 44);
  ckp(0, 0); ckp(0, 1);   /* txn open -> LOCKED(6) */
  commitT(0);
  ckp(0, 0);
  integrity(0, 0);
  commitT(0);
  flush("s25-journal-file");

  /* s26: file churn with autocheckpoint on every commit */
  sb(0x26262626); fileOpen(0);
  ackpt(0, 1);            /* checkpoint threshold 1 */
  for(j=0;j<20;j++){
    for(i=0;i<10;i++) putk(0, 7, 0, 18+i);
    commitT(0); beginTxn(0, 1);
  }
  rdCursor(0,0);
  for(i=0;i<24;i++) getk(0, 7, 0);
  commitT(0);
  integrity(0, 0);
  commitT(0);
  flush("s26-file-churn");

  /* s27: one :memory: handle plus one file handle, crossing traffic */
  sb(0x27272727);
  x(FZ_OP_OPEN); x(0); x(0);        /* flavor 0: memdb */
  fileOpen(1);
  for(i=0;i<30;i++) putk(0, 9, 0, 33);
  for(i=0;i<30;i++) putk(1, 9, 1, 66);
  commitT(0); commitT(1);
  beginTxn(0, 0); rdCursor(1, 0);
  for(i=0;i<12;i++) getk(1, 9, 1);
  commitT(0);
  jmode(1, 0);            /* file WAL->MEMORY outside txn */
  rdCursor(1, 0);
  for(i=0;i<12;i++) getk(1, 9, 1);
  commitT(0);
  integrity(1, 0);
  commitT(0);
  flush("s27-memfile-mixed");

  /* s28: the formerly-banned journal round trip WITH an open cursor.
  ** The WAL->MEMORY->WAL dance used to poison the still-pinned page 1
  ** through the pcache reset on the next WAL restart and fail the next
  ** BEGIN with SQLITE_NOTADB (docs/fuzz-design.md, "开放问题 → 已解决";
  ** engine commit refuses journal-mode changes with live cursors).
  ** Verify every refusal, close the cursor, run the full round trip
  ** cleanly, and confirm the engine serves new work on the file
  ** afterwards. */
  sb(0x28282828ULL); fileOpen(0);
  for(i=0;i<10;i++) putk(0, 9, 0, 30);
  jmode(0, 0);            /* live cursor -> ERROR (same refusal as in-txn) */
  commitT(0);
  jmode(0, 0);            /* cursor still open -> ERROR */
  jmode(0, 1);            /* same-mode request early-returns 5 even with cursor */
  curClose(0);
  jmode(0, 0);            /* clean: -> MEMORY, header version 1 */
  jmode(0, 1);            /* -> WAL, version 2, eager WAL object reopen */
  beginTxn(0, 1);
  curOpen(0, 0, 1);
  for(i=0;i<6;i++) putk(0, 9, 1, 44);
  rdCursor(0, 0);         /* read what survived the round trip */
  for(i=0;i<10;i++) getk(1, 9, 1);
  commitT(0);
  ckp(0, 0);
  integrity(0, 0);
  commitT(0);
  flush("s28-journal-roundtrip");

  /* ---- Target C seeds (fuzz/oomseeds/) ----------------------------- */
  /* Stream = [K byte][8B seed][Target A action ops]; K<2 disables the
  ** injections (plain model-vs-engine pass), K>=2 fails every K-th
  ** allocation.  mkdir happens inside the emitter below. */
  mkdir("fuzz/oomseeds", 0777);
  { static uint8_t obuf[1<<16];
    static size_t on;
    #define ok2(o) obuf[on++] = (uint8_t)(o)
    #define oflush(nm) do{ \
      char op[256]; FILE *of; \
      snprintf(op, sizeof op, "fuzz/oomseeds/%s.bin", nm); \
      of = fopen(op, "wb"); \
      if( of==0 ){ fprintf(stderr, "mkseeds: cannot write %s\n", op); exit(1); } \
      fwrite(obuf, 1, on, of); fclose(of); on = 0; }while(0)
    /* o01: mixed CRUD on memory+file, K=3 */
    { uint64_t sd = 0x0101010101010101ULL; int i2, j2;
      ok2(3); ok2(60);
      for(j2=0;j2<8;j2++) ok2((int)((sd>>(8*j2)) & 0xff) | 0x01);
      /* keep it simple: a shape-valid open (flavor file) then writes */
      ok2(1); ok2(0); ok2(1);            /* open h0 file */
      for(i2=0;i2<12;i2++) putk(0, 9, 0, 40);
      commitT(0);
      rdCursor(0, 0);
      for(i2=0;i2<8;i2++) getk(0, 9, 0);
      beginTxn(0, 1);
      for(i2=0;i2<6;i2++) putk(0, 12, 1, 70);
      spR(0, 1);
      for(i2=0;i2<4;i2++) delk(0, 9, 0);
      commitT(0);
      integrity(0, 0);
      commitT(0);
      jmode(0, 0); jmode(0, 0);          /* same-mode requests only */
      oflush("o01-mixed-k3");
    }
    /* o02: aggressive K=2, savepoint churn */
    { uint64_t sd = 0x0202020202020202ULL; int i2, j2;
      ok2(2); ok2(40);
      for(j2=0;j2<8;j2++) ok2((int)((sd>>(8*j2)) & 0xff) | 0x01);
      beginTxn(0, 1);
      createTree(0);
      ok2(9); ok2(0); ok2(1);            /* cursor_open h0 root0 wr=1 */
      for(i2=0;i2<30;i2++) putk(0, i2%40+2, i2%5, i2%50);
      for(i2=0;i2<10;i2++){ spR(0,1); spRb(0,1); }
      for(i2=0;i2<10;i2++) delk(0, i2%9+2, 0);
      commitT(0);
      integrity(0, 0);
      commitT(0);
      oflush("o02-savepoint-k2");
    }
    /* o03: K=5, valwrite chains + checkpoint */
    { uint64_t sd = 0x0303030303030303ULL; int i2, j2;
      ok2(5); ok2(80);
      for(j2=0;j2<8;j2++) ok2((int)((sd>>(8*j2)) & 0xff) | 0x01);
      fileOpen(0);
      for(i2=0;i2<10;i2++) putk(0, 20, 3, 300);
      commitT(0);
      beginTxn(0, 1);
      rdCursor(0, 0);
      for(i2=0;i2<8;i2++){ vread(0, 0, 100); vwrite(0, 5, 40, 1); }
      commitT(0);
      ckp(0, 0); ckp(0, 1);
      integrity(0, 0);
      commitT(0);
      oflush("o03-valwrite-k5");
    }
    /* o04: K=7, interrupt + integrity sweeps */
    { uint64_t sd = 0x0404040404040404ULL; int i2, j2;
      ok2(7); ok2(50);
      for(j2=0;j2<8;j2++) ok2((int)((sd>>(8*j2)) & 0xff) | 0x01);
      fileOpen(0);
      for(i2=0;i2<15;i2++) putk(0, 11, 2, 120);
      commitT(0);
      setint(0);
      beginTxn(0, 0);
      ok2(26); ok2(0);                    /* integrity h0 root0 */
      rbT(0);
      oflush("o04-interrupt-k7");
    }
    /* o05: K=11, multi-tree + clears */
    { uint64_t sd = 0x0505050505050505ULL; int i2, j2;
      ok2(11); ok2(100);
      for(j2=0;j2<8;j2++) ok2((int)((sd>>(8*j2)) & 0xff) | 0x01);
      beginTxn(0, 1);
      createTree(0); createTree(0); createTree(0);
      ok2(9); ok2(0); ok2(1);
      for(i2=0;i2<9;i2++) putk(0, i2%30+2, i2%5, 60);
      commitT(0);
      beginTxn(0, 1);
      clearTree(0, 2);
      commitT(0);
      integrity(0, 0);
      integrity(0, 2);
      commitT(0);
      oflush("o05-multitree-k11");
      #undef ok2
      #undef oflush
    }
  }

  { /* ---- Target E seeds (fuzz/eseeds/) -------------------------- */
    static uint8_t ebuf[1<<16];
    static size_t en;
    void (*ew)(const char*) = 0;
    (void)ew;
    en = 0;
    /* emitter: same style, but into fuzz/eseeds/ */
    #define eseedFlush(nm) do{ \
      char ep[256]; FILE *ef; \
      snprintf(ep, sizeof ep, "fuzz/eseeds/%s.bin", nm); \
      ef = fopen(ep, "wb"); \
      if( ef==0 ){ fprintf(stderr, "mkseeds: cannot write %s\n", ep); exit(1); } \
      fwrite(ebuf, 1, en, ef); fclose(ef); en = 0; }while(0)
    #define exx(o) ebuf[en++] = (uint8_t)(o)
    mkdir("fuzz/eseeds", 0777);

    /* e01: pure writer+reader alternating, no contention */
    { uint64_t seed = 0xe001000000000001ULL, i2;
      for(i2=0;i2<8;i2++) ebuf[en++] = (uint8_t)(seed>>(8*i2));
      for(i2=0;i2<24;i2++){ exx(1); exx(1); exx(2); exx(30);   /* begin+put */
        if( i2%3==0 ){ exx(4); }                               /* wcommit */
      }
      exx(4); }
    eseedFlush("e01-light");

    /* e02: writer holds, reader reads during the write txn */
    { uint64_t seed = 0xe002000000000002ULL, i2;
      for(i2=0;i2<8;i2++) ebuf[en++] = (uint8_t)(seed>>(8*i2));
      exx(1); exx(1);                                          /* wbegin */
      for(i2=0;i2<8;i2++){
        exx(2); exx(30);                                       /* wput */
        exx(6);                                                /* rbegin */
        for(int j2=0;j2<4;j2++){ exx(7); exx(0); exx((int)(i2*8+j2)); }  /* rget w-keys */
        exx(8);                                                /* rcommit */
      }
      exx(4); }                                                /* wcommit */
    eseedFlush("e02-read-during-write");

    /* e03: writer holds, handle-2 write bundles are contended -> BUSY */
    { uint64_t seed = 0xe003000000000003ULL, i2;
      for(i2=0;i2<8;i2++) ebuf[en++] = (uint8_t)(seed>>(8*i2));
      exx(1); exx(1);
      for(i2=0;i2<12;i2++){ exx(2); exx(30); exx(9); exx(20); }  /* wput+sput(BUSY) */
      exx(4); }
    eseedFlush("e03-sput-contended");

    /* e04: writer free, then handle-2 bundles commit between */
    { uint64_t seed = 0xe004000000000004ULL, i2;
      for(i2=0;i2<8;i2++) ebuf[en++] = (uint8_t)(seed>>(8*i2));
      for(i2=0;i2<10;i2++){
        exx(1); exx(1); exx(2); exx(30); exx(4);                 /* one writer write */
        exx(9); exx(25);                                         /* one sput commit */
      }
      exx(4); }
    eseedFlush("e04-alternate-writers");

    /* e05: checkpoints of every mode between commit pairs */
    { uint64_t seed = 0xe005000000000005ULL, i2;
      for(i2=0;i2<8;i2++) ebuf[en++] = (uint8_t)(seed>>(8*i2));
      for(i2=0;i2<8;i2++){
        exx(1); exx(1); exx(2); exx(30); exx(4);
        exx(10); exx((int)(i2%4));                               /* ckpt mode i2%4 */
      }
      exx(4); }
    eseedFlush("e05-ckpt-modes");

    /* e06: chaos: all ops, fixed mix */
    { uint64_t seed = 0xe006000000000006ULL, i2;
      for(i2=0;i2<8;i2++) ebuf[en++] = (uint8_t)(seed>>(8*i2));
      for(i2=0;i2<150;i2++){
        int m = (int)((i2*7)%10)+1;
        exx(m);
        if( m==1 ) exx(1);
        if( m==2 || m==9 ) exx((int)((i2*13)%48));
        if( m==3 ) exx((int)(i2%100));
        if( m==7 ){ exx(m%2); exx((int)(i2%50)); }
        if( m==10 ) exx((int)(i2%4));
      }
      exx(4); }
    eseedFlush("e06-chaos");
  }

  printf("mkseeds: seeds written to fuzz/seeds/\n");
  return 0;
}